    // then unconditionally restore us to where we were.
    if (!result || isLookAhead) {
        token = saveToken;
        sourceFile.parseDiagnostics.length = saveParseDiagnosticsLength;
        parseErrorBeforeNextFinishedNode = saveParseErrorBeforeNextFinishedNode;
    }

    return result;
