function getContextualTypeForObjectLiteralElement(element: ObjectLiteralElement) {
    let objectLiteral = <ObjectLiteralExpression>element.parent;
    let type = getContextualType(objectLiteral);
    if (type) {
        if (!hasDynamicName(element)) {
